/// <summary>
/// Data entity for the assigned indirect cost components of the indirect component groups
/// (form <c>PSAIndirectCompoundingSetup</c>): date, component, calculation method and rates.
/// </summary>
/// <remarks>
/// The standard has no entity for these lines. Like the standard form, inserting a line creates the
/// compounding rule lines (<c>PSAIndirectCompoundingSetup.insert</c>). For a <c>Percent</c> line, the entity
/// also selects <c>Base amount</c> as the base of every rate type (cost, revenue, invoice) whose rate is
/// not 0, unless that component already has a base selected for that type in the group. This is what
/// <c>Compounding rules</c> &gt; <c>Base amount</c> does in the form.
/// </remarks>
public class HOGpmaIndirectCostRateEntity extends common
{
    #define.BaseAmount('Base amount')
}

Method.Source:
/// <summary>
/// Fills the component name from the component, as the standard form does, if the import leaves it empty.
/// </summary>
/// <param name = "_entityCtx">The entity runtime context.</param>
/// <param name = "_dataSourceCtx">The data source runtime context.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(HOGpmaIndirectCostRateEntity, PSAIndirectCompoundingSetup))
    {
        PSAIndirectCompoundingSetup setup = _dataSourceCtx.getBuffer();

        if (!setup.ComponentName)
        {
            setup.ComponentName = PSAIndirectComponent::find(setup.ComponentId).ComponentName;
        }
    }
}

/// <summary>
/// Inserts the line and selects Base amount as the base of its percentages.
/// </summary>
public void insert()
{
    ttsbegin;
    super();
    this.addBaseAmountRules();
    ttscommit;
}

/// <summary>
/// Updates the line and selects Base amount as the base of percentages that are no longer 0.
/// </summary>
public void update()
{
    ttsbegin;
    super();
    this.addBaseAmountRules();
    ttscommit;
}

/// <summary>
/// Selects Base amount as the base of each rate type with a percentage other than 0.
/// </summary>
private void addBaseAmountRules()
{
    if (this.CalculationMethod == PSAIndirectComponentCalcMethod::Percent)
    {
        this.addBaseAmountRule(PSAIndirectComponentType::Cost,    this.CostRate);
        this.addBaseAmountRule(PSAIndirectComponentType::Revenue, this.RevenueRate);
        this.addBaseAmountRule(PSAIndirectComponentType::Invoice, this.InvoiceRate);
    }
}

/// <summary>
/// Selects Base amount as the base of the component for one rate type, if the component has no base for that type yet.
/// </summary>
/// <param name = "_type">The rate type.</param>
/// <param name = "_rate">The rate of that type; nothing is selected if it is 0.</param>
/// <remarks>
/// Writes the same record as <c>Compounding rules</c> in the standard form (<c>PSAListPanelRelationTable</c>).
/// </remarks>
private void addBaseAmountRule(PSAIndirectComponentType _type, Price _rate)
{
    PSAIndirectCompoundingRulesSelection selection;

    if (_rate)
    {
        select firstonly RecId from selection
            where selection.ComponentGroupId == this.IndirectCostComponentGroup
               && selection.ComponentType    == _type
               && selection.BaseComponentId  == this.IndirectCostComponent;

        if (!selection.RecId)
        {
            selection.ComponentGroupId = this.IndirectCostComponentGroup;
            selection.ComponentType    = _type;
            selection.BaseComponentId  = this.IndirectCostComponent;
            selection.ComponentId      = #BaseAmount;
            selection.insert();
        }
    }
}
